create extension if not exists pgcrypto;
create type public.campaign_status as enum ('draft','discovering','researching','ready_for_review','completed','paused');
create type public.lead_status as enum ('new','researching','qualified','excluded','demo_pending','demo_ready','approved','contacted','interested','meeting','quoted','won','lost');
create type public.demo_status as enum ('pending','rendering','ready','approved','rejected','failed');
create type public.approval_status as enum ('pending','approved','rejected');
create type public.consent_status as enum ('unknown','opted_in','opted_out');
create table public.campaigns(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,niche text not null,city text not null default 'Chennai',state text not null default 'Tamil Nadu',country text not null default 'India',radius_km integer not null default 10 check(radius_km between 1 and 50),max_results integer not null default 100 check(max_results between 1 and 200),filters jsonb not null default '{}'::jsonb,status public.campaign_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,campaign_id uuid references public.campaigns(id) on delete set null,google_place_id text,business_name text not null,phone text,website_url text,instagram_url text,business_category text,business_address text,source text not null default 'google_places',status public.lead_status not null default 'new',exclusion_reason text,evidence jsonb not null default '{}'::jsonb,last_researched_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,google_place_id));
create table public.research_reports(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,findings jsonb not null default '{}'::jsonb,evidence jsonb not null default '[]'::jsonb,confidence numeric(5,2) check(confidence between 0 and 100),created_at timestamptz not null default now());
create table public.lead_scores(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,score integer not null check(score between 0 and 100),priority text not null check(priority in ('high','medium','low','not_qualified')),score_breakdown jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.demo_projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,template_id text not null,brand_data jsonb not null default '{}'::jsonb,asset_paths jsonb not null default '[]'::jsonb,screenshot_path text,width integer not null default 1440,height integer not null default 900,status public.demo_status not null default 'pending',render_error text,created_at timestamptz not null default now());
create table public.approvals(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid references public.leads(id) on delete cascade,demo_id uuid references public.demo_projects(id) on delete cascade,approval_type text not null check(approval_type in ('demo','proposal','campaign','outreach')),status public.approval_status not null default 'pending',reviewer_id uuid references auth.users(id),notes text,reviewed_at timestamptz,created_at timestamptz not null default now());
create table public.contact_consents(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,channel text not null default 'whatsapp',status public.consent_status not null default 'unknown',consent_source text,consent_text text,evidence_url text,consented_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table public.proposals(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,demo_id uuid references public.demo_projects(id) on delete set null,message_text text not null,status text not null default 'draft',template_name text,created_at timestamptz not null default now());
create table public.conversations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,wa_contact_id text,wa_phone_number_id text,last_customer_message_at timestamptz,service_window_expires_at timestamptz,state text not null default 'open',created_at timestamptz not null default now(),unique(owner_id,wa_contact_id));
create table public.messages(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,conversation_id uuid not null references public.conversations(id) on delete cascade,external_message_id text unique,direction text not null check(direction in ('inbound','outbound')),message_type text not null,content text,template_name text,delivery_status text not null default 'queued',created_at timestamptz not null default now());
create table public.followup_tasks(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,conversation_id uuid references public.conversations(id) on delete cascade,scheduled_at timestamptz not null,status text not null default 'pending',attempt_count integer not null default 0,created_at timestamptz not null default now());
create table public.sales_pipeline(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,lead_id uuid not null references public.leads(id) on delete cascade,stage text not null default 'new',meeting_at timestamptz,quoted_amount numeric(12,2),won_amount numeric(12,2),next_action text,updated_at timestamptz not null default now(),unique(owner_id,lead_id));
create index campaigns_owner_status_idx on public.campaigns(owner_id,status);
create index leads_owner_status_idx on public.leads(owner_id,status);
create index leads_campaign_idx on public.leads(campaign_id);
create index research_lead_created_idx on public.research_reports(lead_id,created_at desc);
create index scores_lead_created_idx on public.lead_scores(lead_id,created_at desc);
create index demos_lead_created_idx on public.demo_projects(lead_id,created_at desc);
create index messages_conversation_created_idx on public.messages(conversation_id,created_at desc);
create index followups_due_idx on public.followup_tasks(scheduled_at) where status='pending';
do $$ declare t text; begin foreach t in array array['campaigns','leads','research_reports','lead_scores','demo_projects','approvals','contact_consents','proposals','conversations','messages','followup_tasks','sales_pipeline'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy "owner_select" on public.%I for select to authenticated using (owner_id=(select auth.uid()))',t); execute format('create policy "owner_insert" on public.%I for insert to authenticated with check (owner_id=(select auth.uid()))',t); execute format('create policy "owner_update" on public.%I for update to authenticated using (owner_id=(select auth.uid())) with check (owner_id=(select auth.uid()))',t); execute format('create policy "owner_delete" on public.%I for delete to authenticated using (owner_id=(select auth.uid()))',t); end loop; end $$;
grant select,insert,update,delete on public.campaigns,public.leads,public.research_reports,public.lead_scores,public.demo_projects,public.approvals,public.contact_consents,public.proposals,public.conversations,public.messages,public.followup_tasks,public.sales_pipeline to authenticated;
